/* Incorrect association */
if (x % 4 == 0)
    if (x % 2 == 0) y = 2;
    else
        y = 1;  /* else belongs to inner if! */

/* Correct association */
if (x % 4 == 0) {
    if (x % 2 == 0) y = 2;
} else
    y = 1;  /* now else is connected to outer if */

/* Using if/else if ladder */
if (grade == 'A') {
    printf("Perfect!\n");
} else if (grade == 'B') {
    printf("You did good!\n");
} else if (grade == 'C') {
    printf("You did okay!\n");
} else if (grade == 'D') {
    printf("At least it's not an F!\n");
} else if (grade == 'F') {
    printf("YOU FAILED!\n");
} else {
    printf("That's not a valid grade!\n");
}

/* Using switch */
switch (grade) {
    case 'A':
        printf("Perfect!\n");
        break;
    case 'B':
        printf("You did good!\n");
        break;
    case 'C':
        printf("You did okay!\n");
        break;
    case 'D':
        printf("At least it's not an F!\n");
        break;
    case 'F':
        printf("YOU FAILED!\n");
        break;
    default:
        printf("That's not a valid grade!\n");
}

/* Separate cases */
